#include <sycl/sycl.hpp>
#include <cstdio>
#include <cstdlib>
#include <cmath>
#include <limits>
#include <vector>

template <typename T>
static T ceil_div(T a, T b) { return (a + b - 1) / b; }

static constexpr float kNegInf() {
  return -std::numeric_limits<float>::infinity();
}

// ---- online SumMax combine (variant 6) ----
struct SumMax {
  float maxval;
  float sum;
};

static inline SumMax sumax_combine(SumMax a, SumMax b) {
  bool a_bigger = (a.maxval > b.maxval);
  SumMax bigger = a_bigger ? a : b;
  SumMax smaller = a_bigger ? b : a;
  SumMax r;
  r.maxval = bigger.maxval;
  r.sum = bigger.sum + smaller.sum * sycl::exp(smaller.maxval - bigger.maxval);
  return r;
}
struct SumMaxOp {
  SumMax operator()(const SumMax &a, const SumMax &b) const {
    return sumax_combine(a, b);
  }
};

// ---------------- kernel 1 : one row per work-item, 3 passes ----------------
class SoftmaxK1;
static void run_k1(sycl::queue &q, float *d_out, const float *d_inp, int N,
                   int C) {
  constexpr int B = 256;
  int g = ceil_div(N, B);
  q.submit([&](sycl::handler &h) {
    h.parallel_for<SoftmaxK1>(
        sycl::nd_range<1>(sycl::range<1>(g * B), sycl::range<1>(B)),
        [=](sycl::nd_item<1> it) {
          int i = (int)it.get_global_id(0);
          if (i < N) {
            const float *ir = d_inp + (size_t)i * (size_t)C;
            float *orr = d_out + (size_t)i * (size_t)C;
            float mx = kNegInf();
            for (int j = 0; j < C; ++j)
              if (ir[j] > mx) mx = ir[j];
            double s = 0.0;
            for (int j = 0; j < C; ++j) {
              orr[j] = sycl::exp(ir[j] - mx);
              s += (double)orr[j];
            }
            float inv = (float)(1.0 / s);
            for (int j = 0; j < C; ++j) orr[j] *= inv;
          }
        });
  });
  q.wait();
}

// ---------------- kernel 2 : one row per work-group, local-memory tree ------
// Keeps variant-2 algorithm: coarsened max, tree reduce in local memory,
// exp, coarsened sum, tree reduce, normalize.
class SoftmaxK2;
static void run_k2(sycl::queue &q, float *d_out, const float *d_inp, int N,
                   int C) {
  constexpr int B = 256;
  q.submit([&](sycl::handler &h) {
    sycl::local_accessor<float, 1> shm(sycl::range<1>(B), h);
    h.parallel_for<SoftmaxK2>(
        sycl::nd_range<1>(sycl::range<1>((size_t)N * B), sycl::range<1>(B)),
        [=](sycl::nd_item<1> it) {
          int idx = (int)it.get_group(0);
          int tid = (int)it.get_local_id(0);
          int bs = (int)it.get_local_range(0);
          if (idx >= N) return;
          const float *x = d_inp + (size_t)idx * (size_t)C;
          float mx = kNegInf();
          for (int i = tid; i < C; i += bs) mx = sycl::fmax(mx, x[i]);
          shm[tid] = mx;
          for (int s = bs / 2; s >= 1; s /= 2) {
            it.barrier(sycl::access::fence_space::local_space);
            if (tid < s) shm[tid] = sycl::fmax(shm[tid], shm[tid + s]);
          }
          it.barrier(sycl::access::fence_space::local_space);
          float off = shm[0];
          for (int i = tid; i < C; i += bs)
            d_out[(size_t)idx * (size_t)C + i] = sycl::exp(x[i] - off);
          it.barrier();
          const float *xo = d_out + (size_t)idx * (size_t)C;
          float sv = 0.0f;
          for (int i = tid; i < C; i += bs) sv += xo[i];
          shm[tid] = sv;
          for (int s = bs / 2; s >= 1; s /= 2) {
            it.barrier(sycl::access::fence_space::local_space);
            if (tid < s) shm[tid] += shm[tid + s];
          }
          it.barrier(sycl::access::fence_space::local_space);
          float sum = shm[0];
          for (int i = tid; i < C; i += bs)
            d_out[(size_t)idx * (size_t)C + i] = xo[i] / sum;
        });
  });
  q.wait();
}

// ---------------- kernel 3 : work-group size 32, group reductions ----------
// Keeps variant-3 algorithm: single small work-group per row with
// intra-warp (sub-group / group) reductions for max and sum.
class SoftmaxK3;
static void run_k3(sycl::queue &q, float *d_out, const float *d_inp, int N,
                   int C) {
  constexpr int B = 32;
  q.submit([&](sycl::handler &h) {
    h.parallel_for<SoftmaxK3>(
        sycl::nd_range<1>(sycl::range<1>((size_t)N * B), sycl::range<1>(B)),
        [=](sycl::nd_item<1> it) {
          int idx = (int)it.get_group(0);
          int tid = (int)it.get_local_id(0);
          int bs = (int)it.get_local_range(0);
          if (idx >= N) return;
          sycl::sub_group sg = it.get_sub_group();
          sycl::group<1> grp = it.get_group();
          const float *x = d_inp + (size_t)idx * (size_t)C;
          float mx = kNegInf();
          for (int i = tid; i < C; i += bs) mx = sycl::fmax(mx, x[i]);
          // intra-warp reduction in SYCL terms: group-wide reduction
          // (single warp per group in CUDA == whole group here)
          float off = sycl::reduce_over_group(grp, mx, sycl::maximum<float>());
          // sub-group broadcast equivalent of shfl(broadcast lane 0)
          off = sycl::group_broadcast(sg, off, 0);
          (void)off;
          // recompute via sg broadcast path to keep warp-broadcast idiom
          for (int i = tid; i < C; i += bs)
            d_out[(size_t)idx * (size_t)C + i] = sycl::exp(x[i] - off);
          const float *xo = d_out + (size_t)idx * (size_t)C;
          float sv = 0.0f;
          for (int i = tid; i < C; i += bs) sv += xo[i];
          float tot = sycl::reduce_over_group(grp, sv, sycl::plus<float>());
          tot = sycl::group_broadcast(sg, tot, 0);
          for (int i = tid; i < C; i += bs)
            d_out[(size_t)idx * (size_t)C + i] = xo[i] / tot;
        });
  });
  q.wait();
}

// ---------------- kernel 4 : sub-group + local inter-warp ------------------
// Keeps variant-4 algorithm: per-item coarsening, intra-sub-group reduce,
// local-memory fan-in across sub-groups by item 0, broadcast.
class SoftmaxK4;
static void run_k4(sycl::queue &q, float *d_out, const float *d_inp, int N,
                   int C) {
  constexpr int B = 256;
  q.submit([&](sycl::handler &h) {
    sycl::local_accessor<float, 1> shm(sycl::range<1>(B), h);
    h.parallel_for<SoftmaxK4>(
        sycl::nd_range<1>(sycl::range<1>((size_t)N * B), sycl::range<1>(B)),
        [=](sycl::nd_item<1> it) {
          int idx = (int)it.get_group(0);
          int tid = (int)it.get_local_id(0);
          int bs = (int)it.get_local_range(0);
          if (idx >= N) return;
          sycl::sub_group sg = it.get_sub_group();
          size_t nsg = sg.get_group_range()[0];
          size_t sgid = sg.get_group_id()[0];
          size_t lane = sg.get_local_id()[0];
          const float *x = d_inp + (size_t)idx * (size_t)C;
          float mx = kNegInf();
          for (int i = tid; i < C; i += bs) mx = sycl::fmax(mx, x[i]);
          float wmax = sycl::reduce_over_group(sg, mx, sycl::maximum<float>());
          if (lane == 0) shm[sgid] = wmax;
          it.barrier(sycl::access::fence_space::local_space);
          if (tid == 0) {
            float v = shm[0];
            for (size_t i = 1; i < nsg; ++i) v = sycl::fmax(v, shm[i]);
            shm[0] = v;
          }
          it.barrier(sycl::access::fence_space::local_space);
          float off = shm[0];
          for (int i = tid; i < C; i += bs)
            d_out[(size_t)idx * (size_t)C + i] = sycl::exp(x[i] - off);
          const float *xo = d_out + (size_t)idx * (size_t)C;
          float sv = 0.0f;
          for (int i = tid; i < C; i += bs) sv += xo[i];
          float wsum = sycl::reduce_over_group(sg, sv, sycl::plus<float>());
          if (lane == 0) shm[sgid] = wsum;
          it.barrier(sycl::access::fence_space::local_space);
          if (tid == 0) {
            float v = shm[0];
            for (size_t i = 1; i < nsg; ++i) v += shm[i];
            shm[0] = v;
          }
          it.barrier(sycl::access::fence_space::local_space);
          float sum = shm[0];
          for (int i = tid; i < C; i += bs)
            d_out[(size_t)idx * (size_t)C + i] = xo[i] / sum;
        });
  });
  q.wait();
}

// ---------------- kernel 5 : online, one row per work-item ------------------
class SoftmaxK5;
static void run_k5(sycl::queue &q, float *d_out, const float *d_inp, int N,
                   int C) {
  constexpr int B = 256;
  int g = ceil_div(N, B);
  q.submit([&](sycl::handler &h) {
    h.parallel_for<SoftmaxK5>(
        sycl::nd_range<1>(sycl::range<1>(g * B), sycl::range<1>(B)),
        [=](sycl::nd_item<1> it) {
          int i = (int)it.get_global_id(0);
          if (i < N) {
            const float *ir = d_inp + (size_t)i * (size_t)C;
            float *orr = d_out + (size_t)i * (size_t)C;
            float mx = kNegInf();
            double s = 0.0;
            for (int j = 0; j < C; ++j) {
              float prev = mx;
              float cur = ir[j];
              if (cur > mx) {
                mx = cur;
                s = s * (double)sycl::exp(prev - mx) +
                    (double)sycl::exp(cur - mx);
              } else {
                s += (double)sycl::exp(cur - mx);
              }
            }
            for (int j = 0; j < C; ++j)
              orr[j] = sycl::exp(ir[j] - mx) / (float)s;
          }
        });
  });
  q.wait();
}

// ---------------- kernel 6 : online, one row per sub-group ------------------
// Keeps variant-6 algorithm: per-lane SumMax coarsening + cooperative
// sub-group reduction with the online combine operator.
class SoftmaxK6;
static void run_k6(sycl::queue &q, float *d_out, const float *d_inp, int N,
                   int C) {
  constexpr int B = 256;
  constexpr int kWarp = 32;
  int g = ceil_div(N * kWarp, B);
  q.submit([&](sycl::handler &h) {
    h.parallel_for<SoftmaxK6>(
        sycl::nd_range<1>(sycl::range<1>((size_t)g * B), sycl::range<1>(B)),
        [=](sycl::nd_item<1> it) {
          sycl::sub_group sg = it.get_sub_group();
          size_t nsg = sg.get_group_range()[0];
          size_t sgid = sg.get_group_id()[0];
          size_t lane = sg.get_local_id()[0];
          size_t sgsz = sg.get_local_range()[0];
          size_t idx = it.get_group(0) * nsg + sgid;
          if (idx >= (size_t)N) return;
          const float *x = d_inp + idx * (size_t)C;
          SumMax part{kNegInf(), 0.0f};
          for (int i = (int)lane; i < C; i += (int)sgsz) {
            SumMax e{x[i], 1.0f};
            part = sumax_combine(part, e);
          }
          SumMax tot =
              sycl::reduce_over_group(sg, part, SumMaxOp());
          for (int i = (int)lane; i < C; i += (int)sgsz)
            d_out[idx * (size_t)C + i] =
                sycl::exp(x[i] - tot.maxval) / tot.sum;
        });
  });
  q.wait();
}

// ---------------- kernel 7 : large-C unrolled + sub-group + local ----------
// Keeps variant-7 algorithm: UNROLL_FACTOR register blocking with clamped
// redundant reads, sub-group max/sum, split local storage for max and sum.
class SoftmaxK7;
static void run_k7(sycl::queue &q, float *d_out, const float *d_inp, int N,
                   int C) {
  constexpr int B = 256;
  constexpr int UF = 8;
  q.submit([&](sycl::handler &h) {
    sycl::local_accessor<float, 1> shm(sycl::range<1>(2 * B), h);
    h.parallel_for<SoftmaxK7>(
        sycl::nd_range<1>(sycl::range<1>((size_t)N * B), sycl::range<1>(B)),
        [=](sycl::nd_item<1> it) {
          int idx = (int)it.get_group(0);
          int tid = (int)it.get_local_id(0);
          int bs = (int)it.get_local_range(0);
          if (idx >= N) return;
          sycl::sub_group sg = it.get_sub_group();
          size_t nsg = sg.get_group_range()[0];
          size_t sgid = sg.get_group_id()[0];
          size_t lane = sg.get_local_id()[0];
          float *maxvals = shm.get_pointer();
          float *sumvals = shm.get_pointer() + B;
          const float *x = d_inp + (size_t)idx * (size_t)C;
          float *y = d_out + (size_t)idx * (size_t)C;
          auto clamp_at = [&](int v) { return v < C - 1 ? v : C - 1; };
          float mx = kNegInf();
          if (tid < C) {
            for (int i = tid; i < C; i += bs * UF) {
#pragma unroll
              for (int u = 0; u < UF; ++u)
                mx = sycl::fmax(mx, x[clamp_at(i + u * bs)]);
            }
          }
          float wmax = sycl::reduce_over_group(sg, mx, sycl::maximum<float>());
          if (lane == 0) maxvals[sgid] = wmax;
          it.barrier(sycl::access::fence_space::local_space);
          if (tid == 0) {
            float v = maxvals[0];
#pragma unroll
            for (size_t i = 1; i < 64; ++i) {
              if (i < nsg) v = sycl::fmax(v, maxvals[i]);
            }
            maxvals[0] = v;
          }
          it.barrier(sycl::access::fence_space::local_space);
          float off = maxvals[0];
          float sv = 0.0f;
          if (tid < C) {
            for (int i = tid; i < C; i += bs * UF) {
              float regs[UF];
#pragma unroll
              for (int u = 0; u < UF; ++u) regs[u] = x[clamp_at(i + u * bs)];
#pragma unroll
              for (int u = 0; u < UF; ++u) {
                if (i + u * bs < C) {
                  float o = sycl::exp(regs[u] - off);
                  y[clamp_at(i + u * bs)] = o;
                  sv += o;
                }
              }
            }
          }
          float wsum = sycl::reduce_over_group(sg, sv, sycl::plus<float>());
          if (lane == 0) sumvals[sgid] = wsum;
          it.barrier(sycl::access::fence_space::local_space);
          if (tid == 0) {
            float v = sumvals[0];
#pragma unroll
            for (size_t i = 1; i < 64; ++i) {
              if (i < nsg) v += sumvals[i];
            }
            sumvals[0] = v;
          }
          it.barrier(sycl::access::fence_space::local_space);
          float sum = sumvals[0];
          if (tid < C) {
            for (int i = tid; i < C; i += bs * UF) {
              float regs[UF];
#pragma unroll
              for (int u = 0; u < UF; ++u) regs[u] = y[clamp_at(i + u * bs)];
#pragma unroll
              for (int u = 0; u < UF; ++u) {
                if (i + u * bs < C) y[i + u * bs] = regs[u] / sum;
              }
            }
          }
        });
  });
  q.wait();
}

// ---------------- kernel 8 : online, one row per sub-group, warp merge -----
// Keeps variant-8 algorithm: per-lane online max/sum coarsening then the
// online warp-merge reduction with shift_group_left exchanges.
class SoftmaxK8;
static void run_k8(sycl::queue &q, float *d_out, const float *d_inp, int N,
                   int C) {
  constexpr int B = 256;
  constexpr int kWarp = 32;
  int g = ceil_div(N * kWarp, B);
  q.submit([&](sycl::handler &h) {
    h.parallel_for<SoftmaxK8>(
        sycl::nd_range<1>(sycl::range<1>((size_t)g * B), sycl::range<1>(B)),
        [=](sycl::nd_item<1> it) {
          sycl::sub_group sg = it.get_sub_group();
          size_t nsg = sg.get_group_range()[0];
          size_t sgid = sg.get_group_id()[0];
          size_t lane = sg.get_local_id()[0];
          size_t sgsz = sg.get_local_range()[0];
          size_t row = it.get_group(0) * nsg + sgid;
          if (row >= (size_t)N) return;
          const float *x = d_inp + row * (size_t)C;
          float *y = d_out + row * (size_t)C;
          float mx = kNegInf(), sv = 0.0f;
          for (int i = (int)lane; i < C; i += (int)sgsz) {
            float bigger = sycl::fmax(mx, x[i]);
            sv = sv * sycl::exp(mx - bigger) + sycl::exp(x[i] - bigger);
            mx = bigger;
          }
          for (size_t off = sgsz / 2; off > 0; off >>= 1) {
            float omx = sycl::shift_group_left(sg, mx, off);
            float osv = sycl::shift_group_left(sg, sv, off);
            if (omx > mx) {
              sv *= sycl::exp(mx - omx);
              mx = omx;
            } else {
              osv *= sycl::exp(omx - mx);
            }
            sv += osv;
          }
          mx = sycl::group_broadcast(sg, mx, 0);
          sv = sycl::group_broadcast(sg, sv, 0);
          for (int i = (int)lane; i < C; i += (int)sgsz)
            y[i] = sycl::exp(x[i] - mx) / sv;
        });
  });
  q.wait();
}

int main(int argc, char **argv) {
  if (argc != 6) {
    std::fprintf(stderr, "usage: %s <input> <output> B T V\n", argv[0]);
    return 2;
  }
  const int B = std::atoi(argv[3]);
  const int T = std::atoi(argv[4]);
  const int V = std::atoi(argv[5]);
  size_t N = (size_t)B * (size_t)T;
  size_t C = (size_t)V;
  std::FILE *fin = std::fopen(argv[1], "rb");
  if (!fin) {
    std::perror(argv[1]);
    return 2;
  }
  std::vector<float> inp(N * C);
  if (std::fread(inp.data(), sizeof(float), N * C, fin) != N * C) {
    std::fprintf(stderr, "input too short at inp\n");
    return 2;
  }
  std::vector<int> outliers(N * 3);
  if (std::fread(outliers.data(), sizeof(int), N * 3, fin) != N * 3) {
    std::fprintf(stderr, "input too short at outliers\n");
    return 2;
  }
  std::fclose(fin);
  for (int k = 0; k < 3; ++k)
    for (size_t j = 0; j < N; ++j) inp[j * C + outliers[j * 3 + k]] *= 20.0f;

  sycl::queue q{sycl::default_selector_v};
  float *d_inp = sycl::malloc_device<float>(N * C, q);
  float *d_out = sycl::malloc_device<float>(N * C, q);
  if (!d_inp || !d_out) {
    std::fprintf(stderr, "device alloc failed\n");
    return 1;
  }
  q.memcpy(d_inp, inp.data(), sizeof(float) * N * C).wait();
  std::vector<float> out(N * C);
  std::FILE *fout = std::fopen(argv[2], "wb");
  if (!fout) {
    std::perror(argv[2]);
    return 2;
  }
  const int variants[8] = {1, 2, 3, 4, 5, 6, 7, 8};
  for (int vi = 0; vi < 8; ++vi) {
    q.memset(d_out, 0, sizeof(float) * N * C).wait();
    switch (variants[vi]) {
      case 1: run_k1(q, d_out, d_inp, (int)N, (int)C); break;
      case 2: run_k2(q, d_out, d_inp, (int)N, (int)C); break;
      case 3: run_k3(q, d_out, d_inp, (int)N, (int)C); break;
      case 4: run_k4(q, d_out, d_inp, (int)N, (int)C); break;
      case 5: run_k5(q, d_out, d_inp, (int)N, (int)C); break;
      case 6: run_k6(q, d_out, d_inp, (int)N, (int)C); break;
      case 7: run_k7(q, d_out, d_inp, (int)N, (int)C); break;
      case 8: run_k8(q, d_out, d_inp, (int)N, (int)C); break;
    }
    q.memcpy(out.data(), d_out, sizeof(float) * N * C).wait();
    std::fwrite(out.data(), sizeof(float), N * C, fout);
  }
  std::fclose(fout);
  sycl::free(d_inp, q);
  sycl::free(d_out, q);
  return 0;
}

#include <sycl/sycl.hpp>
#include <cstdio>
#include <cstdlib>
#include <cmath>
#include <limits>
#include <vector>

template <typename T>
static T ceil_div(T a, T b) { return (a + b - 1) / b; }

static constexpr float kNegInf() {
  return -std::numeric_limits<float>::infinity();
}

// ---- online SumMax combine (variant 6) ----
struct SumMax {
  float maxval;
  float sum;
};

static inline SumMax sumax_combine(SumMax a, SumMax b) {
  bool a_bigger = (a.maxval > b.maxval);
  SumMax bigger = a_bigger ? a : b;
  SumMax smaller = a_bigger ? b : a;
  SumMax r;
  r.maxval = bigger.maxval;
  r.sum = bigger.sum + smaller.sum * sycl::exp(smaller.maxval - bigger.maxval);
  return r;
}
struct SumMaxOp {
  SumMax operator()(const SumMax &a, const SumMax &b) const {
    return sumax_combine(a, b);
  }
};

// ---------------- kernel 1 : one row per work-item, 3 passes ----------------
class SoftmaxK1;
static void run_k1(sycl::queue &q, float *d_out, const float *d_inp, int N,
                   int C) {
  constexpr int B = 256;
  int g = ceil_div(N, B);
  q.submit([&](sycl::handler &h) {
    h.parallel_for<SoftmaxK1>(
        sycl::nd_range<1>(sycl::range<1>(g * B), sycl::range<1>(B)),
        [=](sycl::nd_item<1> it) {
          int i = (int)it.get_global_id(0);
          if (i < N) {
            const float *ir = d_inp + (size_t)i * (size_t)C;
            float *orr = d_out + (size_t)i * (size_t)C;
            float mx = kNegInf();
            for (int j = 0; j < C; ++j)
              if (ir[j] > mx) mx = ir[j];
            double s = 0.0;
            for (int j = 0; j < C; ++j) {
              orr[j] = sycl::exp(ir[j] - mx);
              s += (double)orr[j];
            }
            float inv = (float)(1.0 / s);
            for (int j = 0; j < C; ++j) orr[j] *= inv;
          }
        });
  });
  q.wait();
}

// ---------------- kernel 2 : one row per work-group, local-memory tree ------
// Keeps variant-2 algorithm: coarsened max, tree reduce in local memory,
// exp, coarsened sum, tree reduce, normalize.
class SoftmaxK2;
static void run_k2(sycl::queue &q, float *d_out, const float *d_inp, int N,
                   int C) {
  constexpr int B = 256;
  q.submit([&](sycl::handler &h) {
    sycl::local_accessor<float, 1> shm(sycl::range<1>(B), h);
    h.parallel_for<SoftmaxK2>(
        sycl::nd_range<1>(sycl::range<1>((size_t)N * B), sycl::range<1>(B)),
        [=](sycl::nd_item<1> it) {
          int idx = (int)it.get_group(0);
          int tid = (int)it.get_local_id(0);
          int bs = (int)it.get_local_range(0);
          if (idx >= N) return;
          const float *x = d_inp + (size_t)idx * (size_t)C;
          float mx = kNegInf();
          for (int i = tid; i < C; i += bs) mx = sycl::fmax(mx, x[i]);
          shm[tid] = mx;
          for (int s = bs / 2; s >= 1; s /= 2) {
            it.barrier(sycl::access::fence_space::local_space);
            if (tid < s) shm[tid] = sycl::fmax(shm[tid], shm[tid + s]);
          }
          it.barrier(sycl::access::fence_space::local_space);
          float off = shm[0];
          for (int i = tid; i < C; i += bs)
            d_out[(size_t)idx * (size_t)C + i] = sycl::exp(x[i] - off);
          it.barrier();
          const float *xo = d_out + (size_t)idx * (size_t)C;
          float sv = 0.0f;
          for (int i = tid; i < C; i += bs) sv += xo[i];
          shm[tid] = sv;
          for (int s = bs / 2; s >= 1; s /= 2) {
            it.barrier(sycl::access::fence_space::local_space);
            if (tid < s) shm[tid] += shm[tid + s];
          }
          it.barrier(sycl::access::fence_space::local_space);
          float sum = shm[0];
          for (int i = tid; i < C; i += bs)
            d_out[(size_t)idx * (size_t)C + i] = xo[i] / sum;
        });
  });
  q.wait();
}

// ---------------- kernel 3 : work-group size 32, group reductions ----------
// Keeps variant-3 algorithm: single small work-group per row with
// intra-warp (sub-group / group) reductions for max and sum.
class SoftmaxK3;
static void run_k3(sycl::queue &q, float *d_out, const float *d_inp, int N,
                   int C) {
  constexpr int B = 32;
  q.submit([&](sycl::handler &h) {
    h.parallel_for<SoftmaxK3>(
        sycl::nd_range<1>(sycl::range<1>((size_t)N * B), sycl::range<1>(B)),
        [=](sycl::nd_item<1> it) {
          int idx = (int)it.get_group(0);
          int tid = (int)it.get_local_id(0);
          int bs = (int)it.get_local_range(0);
          if (idx >= N) return;
          sycl::sub_group sg = it.get_sub_group();
          sycl::group<1> grp = it.get_group();
          const float *x = d_inp + (size_t)idx * (size_t)C;
          float mx = kNegInf();
          for (int i = tid; i < C; i += bs) mx = sycl::fmax(mx, x[i]);
          // intra-warp reduction in SYCL terms: group-wide reduction
          // (single warp per group in CUDA == whole group here)
          float off = sycl::reduce_over_group(grp, mx, sycl::maximum<float>());
          // sub-group broadcast equivalent of shfl(broadcast lane 0)
          off = sycl::group_broadcast(sg, off, 0);
          (void)off;
          // recompute via sg broadcast path to keep warp-broadcast idiom
          for (int i = tid; i < C; i += bs)
            d_out[(size_t)idx * (size_t)C + i] = sycl::exp(x[i] - off);
          const float *xo = d_out + (size_t)idx * (size_t)C;
          float sv = 0.0f;
          for (int i = tid; i < C; i += bs) sv += xo[i];
          float tot = sycl::reduce_over_group(grp, sv, sycl::plus<float>());
          tot = sycl::group_broadcast(sg, tot, 0);
          for (int i = tid; i < C; i += bs)
            d_out[(size_t)idx * (size_t)C + i] = xo[i] / tot;
        });
  });
  q.wait();
}

// ---------------- kernel 4 : sub-group + local inter-warp ------------------
// Keeps variant-4 algorithm: per-item coarsening, intra-sub-group reduce,
// local-memory fan-in across sub-groups by item 0, broadcast.
class SoftmaxK4;
static void run_k4(sycl::queue &q, float *d_out, const float *d_inp, int N,
                   int C) {
  constexpr int B = 256;
  q.submit([&](sycl::handler &h) {
    sycl::local_accessor<float, 1> shm(sycl::range<1>(B), h);
    h.parallel_for<SoftmaxK4>(
        sycl::nd_range<1>(sycl::range<1>((size_t)N * B), sycl::range<1>(B)),
        [=](sycl::nd_item<1> it) {
          int idx = (int)it.get_group(0);
          int tid = (int)it.get_local_id(0);
          int bs = (int)it.get_local_range(0);
          if (idx >= N) return;
          sycl::sub_group sg = it.get_sub_group();
          size_t nsg = sg.get_group_range()[0];
          size_t sgid = sg.get_group_id()[0];
          size_t lane = sg.get_local_id()[0];
          const float *x = d_inp + (size_t)idx * (size_t)C;
          float mx = kNegInf();
          for (int i = tid; i < C; i += bs) mx = sycl::fmax(mx, x[i]);
          float wmax = sycl::reduce_over_group(sg, mx, sycl::maximum<float>());
          if (lane == 0) shm[sgid] = wmax;
          it.barrier(sycl::access::fence_space::local_space);
          if (tid == 0) {
            float v = shm[0];
            for (size_t i = 1; i < nsg; ++i) v = sycl::fmax(v, shm[i]);
            shm[0] = v;
          }
          it.barrier(sycl::access::fence_space::local_space);
          float off = shm[0];
          for (int i = tid; i < C; i += bs)
            d_out[(size_t)idx * (size_t)C + i] = sycl::exp(x[i] - off);
          const float *xo = d_out + (size_t)idx * (size_t)C;
          float sv = 0.0f;
          for (int i = tid; i < C; i += bs) sv += xo[i];
          float wsum = sycl::reduce_over_group(sg, sv, sycl::plus<float>());
          if (lane == 0) shm[sgid] = wsum;
          it.barrier(sycl::access::fence_space::local_space);
          if (tid == 0) {
            float v = shm[0];
            for (size_t i = 1; i < nsg; ++i) v += shm[i];
            shm[0] = v;
          }
          it.barrier(sycl::access::fence_space::local_space);
          float sum = shm[0];
          for (int i = tid; i < C; i += bs)
            d_out[(size_t)idx * (size_t)C + i] = xo[i] / sum;
        });
  });
  q.wait();
}

// ---------------- kernel 5 : online, one row per work-item ------------------
class SoftmaxK5;
static void run_k5(sycl::queue &q, float *d_out, const float *d_inp, int N,
                   int C) {
  constexpr int B = 256;
  int g = ceil_div(N, B);
  q.submit([&](sycl::handler &h) {
    h.parallel_for<SoftmaxK5>(
        sycl::nd_range<1>(sycl::range<1>(g * B), sycl::range<1>(B)),
        [=](sycl::nd_item<1> it) {
          int i = (int)it.get_global_id(0);
          if (i < N) {
            const float *ir = d_inp + (size_t)i * (size_t)C;
            float *orr = d_out + (size_t)i * (size_t)C;
            float mx = kNegInf();
            double s = 0.0;
            for (int j = 0; j < C; ++j) {
              float prev = mx;
              float cur = ir[j];
              if (cur > mx) {
                mx = cur;
                s = s * (double)sycl::exp(prev - mx) +
                    (double)sycl::exp(cur - mx);
              } else {
                s += (double)sycl::exp(cur - mx);
              }
            }
            for (int j = 0; j < C; ++j)
              orr[j] = sycl::exp(ir[j] - mx) / (float)s;
          }
        });
  });
  q.wait();
}

// ---------------- kernel 6 : online, one row per sub-group ------------------
// Keeps variant-6 algorithm: per-lane SumMax coarsening + cooperative
// sub-group reduction with the online combine operator.
class SoftmaxK6;
static void run_k6(sycl::queue &q, float *d_out, const float *d_inp, int N,
                   int C) {
  constexpr int B = 256;
  constexpr int kWarp = 32;
  int g = ceil_div(N * kWarp, B);
  q.submit([&](sycl::handler &h) {
    h.parallel_for<SoftmaxK6>(
        sycl::nd_range<1>(sycl::range<1>((size_t)g * B), sycl::range<1>(B)),
        [=](sycl::nd_item<1> it) {
          sycl::sub_group sg = it.get_sub_group();
          size_t nsg = sg.get_group_range()[0];
          size_t sgid = sg.get_group_id()[0];
          size_t lane = sg.get_local_id()[0];
          size_t sgsz = sg.get_local_range()[0];
          size_t idx = it.get_group(0) * nsg + sgid;
          if (idx >= (size_t)N) return;
          const float *x = d_inp + idx * (size_t)C;
          SumMax part{kNegInf(), 0.0f};
          for (int i = (int)lane; i < C; i += (int)sgsz) {
            SumMax e{x[i], 1.0f};
            part = sumax_combine(part, e);
          }
          SumMax tot =
              sycl::reduce_over_group(sg, part, SumMaxOp());
          for (int i = (int)lane; i < C; i += (int)sgsz)
            d_out[idx * (size_t)C + i] =
                sycl::exp(x[i] - tot.maxval) / tot.sum;
        });
  });
  q.wait();
}

// ---------------- kernel 7 : large-C unrolled + sub-group + local ----------
// Keeps variant-7 algorithm: UNROLL_FACTOR register blocking with clamped
// redundant reads, sub-group max/sum, split local storage for max and sum.
class SoftmaxK7;
static void run_k7(sycl::queue &q, float *d_out, const float *d_inp, int N,
                   int C) {
  constexpr int B = 256;
  constexpr int UF = 8;
  q.submit([&](sycl::handler &h) {
    sycl::local_accessor<float, 1> shm(sycl::range<1>(2 * B), h);
    h.parallel_for<SoftmaxK7>(
        sycl::nd_range<1>(sycl::range<1>((size_t)N * B), sycl::range<1>(B)),
        [=](sycl::nd_item<1> it) {
          int idx = (int)it.get_group(0);
          int tid = (int)it.get_local_id(0);
          int bs = (int)it.get_local_range(0);
          if (idx >= N) return;
          sycl::sub_group sg = it.get_sub_group();
          size_t nsg = sg.get_group_range()[0];
          size_t sgid = sg.get_group_id()[0];
          size_t lane = sg.get_local_id()[0];
          float *maxvals = shm.get_pointer();
          float *sumvals = shm.get_pointer() + B;
          const float *x = d_inp + (size_t)idx * (size_t)C;
          float *y = d_out + (size_t)idx * (size_t)C;
          auto clamp_at = [&](int v) { return v < C - 1 ? v : C - 1; };
          float mx = kNegInf();
          if (tid < C) {
            for (int i = tid; i < C; i += bs * UF) {
#pragma unroll
              for (int u = 0; u < UF; ++u)
                mx = sycl::fmax(mx, x[clamp_at(i + u * bs)]);
            }
          }
          float wmax = sycl::reduce_over_group(sg, mx, sycl::maximum<float>());
          if (lane == 0) maxvals[sgid] = wmax;
          it.barrier(sycl::access::fence_space::local_space);
          if (tid == 0) {
            float v = maxvals[0];
#pragma unroll
            for (size_t i = 1; i < 64; ++i) {
              if (i < nsg) v = sycl::fmax(v, maxvals[i]);
            }
            maxvals[0] = v;
          }
          it.barrier(sycl::access::fence_space::local_space);
          float off = maxvals[0];
          float sv = 0.0f;
          if (tid < C) {
            for (int i = tid; i < C; i += bs * UF) {
              float regs[UF];
#pragma unroll
              for (int u = 0; u < UF; ++u) regs[u] = x[clamp_at(i + u * bs)];
#pragma unroll
              for (int u = 0; u < UF; ++u) {
                if (i + u * bs < C) {
                  float o = sycl::exp(regs[u] - off);
                  y[clamp_at(i + u * bs)] = o;
                  sv += o;
                }
              }
            }
          }
          float wsum = sycl::reduce_over_group(sg, sv, sycl::plus<float>());
          if (lane == 0) sumvals[sgid] = wsum;
          it.barrier(sycl::access::fence_space::local_space);
          if (tid == 0) {
            float v = sumvals[0];
#pragma unroll
            for (size_t i = 1; i < 64; ++i) {
              if (i < nsg) v += sumvals[i];
            }
            sumvals[0] = v;
          }
          it.barrier(sycl::access::fence_space::local_space);
          float sum = sumvals[0];
          if (tid < C) {
            for (int i = tid; i < C; i += bs * UF) {
              float regs[UF];
#pragma unroll
              for (int u = 0; u < UF; ++u) regs[u] = y[clamp_at(i + u * bs)];
#pragma unroll
              for (int u = 0; u < UF; ++u) {
                if (i + u * bs < C) y[i + u * bs] = regs[u] / sum;
              }
            }
          }
        });
  });
  q.wait();
}

// ---------------- kernel 8 : online, one row per sub-group, warp merge -----
// Keeps variant-8 algorithm: per-lane online max/sum coarsening then the
// online warp-merge reduction with shift_group_left exchanges.
class SoftmaxK8;
static void run_k8(sycl::queue &q, float *d_out, const float *d_inp, int N,
                   int C) {
  constexpr int B = 256;
  constexpr int kWarp = 32;
  int g = ceil_div(N * kWarp, B);
  q.submit([&](sycl::handler &h) {
    h.parallel_for<SoftmaxK8>(
        sycl::nd_range<1>(sycl::range<1>((size_t)g * B), sycl::range<1>(B)),
        [=](sycl::nd_item<1> it) {
          sycl::sub_group sg = it.get_sub_group();
          size_t nsg = sg.get_group_range()[0];
          size_t sgid = sg.get_group_id()[0];
          size_t lane = sg.get_local_id()[0];
          size_t sgsz = sg.get_local_range()[0];
          size_t row = it.get_group(0) * nsg + sgid;
          if (row >= (size_t)N) return;
          const float *x = d_inp + row * (size_t)C;
          float *y = d_out + row * (size_t)C;
          float mx = kNegInf(), sv = 0.0f;
          for (int i = (int)lane; i < C; i += (int)sgsz) {
            float bigger = sycl::fmax(mx, x[i]);
            sv = sv * sycl::exp(mx - bigger) + sycl::exp(x[i] - bigger);
            mx = bigger;
          }
          for (size_t off = sgsz / 2; off > 0; off >>= 1) {
            float omx = sycl::shift_group_left(sg, mx, off);
            float osv = sycl::shift_group_left(sg, sv, off);
            if (omx > mx) {
              sv *= sycl::exp(mx - omx);
              mx = omx;
            } else {
              osv *= sycl::exp(omx - mx);
            }
            sv += osv;
          }
          mx = sycl::group_broadcast(sg, mx, 0);
          sv = sycl::group_broadcast(sg, sv, 0);
          for (int i = (int)lane; i < C; i += (int)sgsz)
            y[i] = sycl::exp(x[i] - mx) / sv;
        });
  });
  q.wait();
}

int main(int argc, char **argv) {
  if (argc != 6) {
    std::fprintf(stderr, "usage: %s <input> <output> B T V\n", argv[0]);
    return 2;
  }
  const int B = std::atoi(argv[3]);
  const int T = std::atoi(argv[4]);
  const int V = std::atoi(argv[5]);
  size_t N = (size_t)B * (size_t)T;
  size_t C = (size_t)V;
  std::FILE *fin = std::fopen(argv[1], "rb");
  if (!fin) {
    std::perror(argv[1]);
    return 2;
  }
  std::vector<float> inp(N * C);
  if (std::fread(inp.data(), sizeof(float), N * C, fin) != N * C) {
    std::fprintf(stderr, "input too short at inp\n");
    return 2;
  }
  std::vector<int> outliers(N * 3);
  if (std::fread(outliers.data(), sizeof(int), N * 3, fin) != N * 3) {
    std::fprintf(stderr, "input too short at outliers\n");
    return 2;
  }
  std::fclose(fin);
  for (int k = 0; k < 3; ++k)
    for (size_t j = 0; j < N; ++j) inp[j * C + outliers[j * 3 + k]] *= 20.0f;

  sycl::queue q{sycl::default_selector_v};
  float *d_inp = sycl::malloc_device<float>(N * C, q);
  float *d_out = sycl::malloc_device<float>(N * C, q);
  if (!d_inp || !d_out) {
    std::fprintf(stderr, "device alloc failed\n");
    return 1;
  }
  q.memcpy(d_inp, inp.data(), sizeof(float) * N * C).wait();
  std::vector<float> out(N * C);
  std::FILE *fout = std::fopen(argv[2], "wb");
  if (!fout) {
    std::perror(argv[2]);
    return 2;
  }
  const int variants[8] = {1, 2, 3, 4, 5, 6, 7, 8};
  for (int vi = 0; vi < 8; ++vi) {
    q.memset(d_out, 0, sizeof(float) * N * C).wait();
    switch (variants[vi]) {
      case 1: run_k1(q, d_out, d_inp, (int)N, (int)C); break;
      case 2: run_k2(q, d_out, d_inp, (int)N, (int)C); break;
      case 3: run_k3(q, d_out, d_inp, (int)N, (int)C); break;
      case 4: run_k4(q, d_out, d_inp, (int)N, (int)C); break;
      case 5: run_k5(q, d_out, d_inp, (int)N, (int)C); break;
      case 6: run_k6(q, d_out, d_inp, (int)N, (int)C); break;
      case 7: run_k7(q, d_out, d_inp, (int)N, (int)C); break;
      case 8: run_k8(q, d_out, d_inp, (int)N, (int)C); break;
    }
    q.memcpy(out.data(), d_out, sizeof(float) * N * C).wait();
    std::fwrite(out.data(), sizeof(float), N * C, fout);
  }
  std::fclose(fout);
  sycl::free(d_inp, q);
  sycl::free(d_out, q);
  return 0;
}

#include <sycl/sycl.hpp>
#include <cstdio>
#include <cstdlib>
#include <cmath>
#include <limits>
#include <vector>

template <typename T>
static T ceil_div(T a, T b) { return (a + b - 1) / b; }

static constexpr float kNegInf() {
  return -std::numeric_limits<float>::infinity();
}

// ---- online SumMax combine (variant 6) ----
struct SumMax {
  float maxval;
  float sum;
};

static inline SumMax sumax_combine(SumMax a, SumMax b) {
  bool a_bigger = (a.maxval > b.maxval);
  SumMax bigger = a_bigger ? a : b;
  SumMax smaller = a_bigger ? b : a;
  SumMax r;
  r.maxval = bigger.maxval;
  r.sum = bigger.sum + smaller.sum * sycl::exp(smaller.maxval - bigger.maxval);
  return r;
}
struct SumMaxOp {
  SumMax operator()(const SumMax &a, const SumMax &b) const {
    return sumax_combine(a, b);
  }
};

// ---------------- kernel 1 : one row per work-item, 3 passes ----------------
class SoftmaxK1;
static void run_k1(sycl::queue &q, float *d_out, const float *d_inp, int N,
                   int C) {
  constexpr int B = 256;
  int g = ceil_div(N, B);
  q.submit([&](sycl::handler &h) {
    h.parallel_for<SoftmaxK1>(
        sycl::nd_range<1>(sycl::range<1>(g * B), sycl::range<1>(B)),
        [=](sycl::nd_item<1> it) {
          int i = (int)it.get_global_id(0);
          if (i < N) {
            const float *ir = d_inp + (size_t)i * (size_t)C;
            float *orr = d_out + (size_t)i * (size_t)C;
            float mx = kNegInf();
            for (int j = 0; j < C; ++j)
              if (ir[j] > mx) mx = ir[j];
            double s = 0.0;
            for (int j = 0; j < C; ++j) {
              orr[j] = sycl::exp(ir[j] - mx);
              s += (double)orr[j];
            }
            float inv = (float)(1.0 / s);
            for (int j = 0; j < C; ++j) orr[j] *= inv;
          }
        });
  });
  q.wait();
}

// ---------------- kernel 2 : one row per work-group, local-memory tree ------
// Keeps variant-2 algorithm: coarsened max, tree reduce in local memory,
// exp, coarsened sum, tree reduce, normalize.
class SoftmaxK2;
static void run_k2(sycl::queue &q, float *d_out, const float *d_inp, int N,
                   int C) {
  constexpr int B = 256;
  q.submit([&](sycl::handler &h) {
    sycl::local_accessor<float, 1> shm(sycl::range<1>(B), h);
    h.parallel_for<SoftmaxK2>(
        sycl::nd_range<1>(sycl::range<1>((size_t)N * B), sycl::range<1>(B)),
        [=](sycl::nd_item<1> it) {
          int idx = (int)it.get_group(0);
          int tid = (int)it.get_local_id(0);
          int bs = (int)it.get_local_range(0);
          if (idx >= N) return;
          const float *x = d_inp + (size_t)idx * (size_t)C;
          float mx = kNegInf();
          for (int i = tid; i < C; i += bs) mx = sycl::fmax(mx, x[i]);
          shm[tid] = mx;
          for (int s = bs / 2; s >= 1; s /= 2) {
            it.barrier(sycl::access::fence_space::local_space);
            if (tid < s) shm[tid] = sycl::fmax(shm[tid], shm[tid + s]);
          }
          it.barrier(sycl::access::fence_space::local_space);
          float off = shm[0];
          for (int i = tid; i < C; i += bs)
            d_out[(size_t)idx * (size_t)C + i] = sycl::exp(x[i] - off);
          it.barrier();
          const float *xo = d_out + (size_t)idx * (size_t)C;
          float sv = 0.0f;
          for (int i = tid; i < C; i += bs) sv += xo[i];
          shm[tid] = sv;
          for (int s = bs / 2; s >= 1; s /= 2) {
            it.barrier(sycl::access::fence_space::local_space);
            if (tid < s) shm[tid] += shm[tid + s];
          }
          it.barrier(sycl::access::fence_space::local_space);
          float sum = shm[0];
          for (int i = tid; i < C; i += bs)
            d_out[(size_t)idx * (size_t)C + i] = xo[i] / sum;
        });
  });
  q.wait();
}

// ---------------- kernel 3 : work-group size 32, group reductions ----------
// Keeps variant-3 algorithm: single small work-group per row with
// intra-warp (sub-group / group) reductions for max and sum.
class SoftmaxK3;
static void run_k3(sycl::queue &q, float *d_out, const float *d_inp, int N,
                   int C) {
  constexpr int B = 32;
  q.submit([&](sycl::handler &h) {
    h.parallel_for<SoftmaxK3>(
        sycl::nd_range<1>(sycl::range<1>((size_t)N * B), sycl::range<1>(B)),
        [=](sycl::nd_item<1> it) {
          int idx = (int)it.get_group(0);
          int tid = (int)it.get_local_id(0);
          int bs = (int)it.get_local_range(0);
          if (idx >= N) return;
          sycl::sub_group sg = it.get_sub_group();
          sycl::group<1> grp = it.get_group();
          const float *x = d_inp + (size_t)idx * (size_t)C;
          float mx = kNegInf();
          for (int i = tid; i < C; i += bs) mx = sycl::fmax(mx, x[i]);
          // intra-warp reduction in SYCL terms: group-wide reduction
          // (single warp per group in CUDA == whole group here)
          float off = sycl::reduce_over_group(grp, mx, sycl::maximum<float>());
          // sub-group broadcast equivalent of shfl(broadcast lane 0)
          off = sycl::group_broadcast(sg, off, 0);
          (void)off;
          // recompute via sg broadcast path to keep warp-broadcast idiom
          for (int i = tid; i < C; i += bs)
            d_out[(size_t)idx * (size_t)C + i] = sycl::exp(x[i] - off);
          const float *xo = d_out + (size_t)idx * (size_t)C;
          float sv = 0.0f;
          for (int i = tid; i < C; i += bs) sv += xo[i];
          float tot = sycl::reduce_over_group(grp, sv, sycl::plus<float>());
          tot = sycl::group_broadcast(sg, tot, 0);
          for (int i = tid; i < C; i += bs)
            d_out[(size_t)idx * (size_t)C + i] = xo[i] / tot;
        });
  });
  q.wait();
}

// ---------------- kernel 4 : sub-group + local inter-warp ------------------
// Keeps variant-4 algorithm: per-item coarsening, intra-sub-group reduce,
// local-memory fan-in across sub-groups by item 0, broadcast.
class SoftmaxK4;
static void run_k4(sycl::queue &q, float *d_out, const float *d_inp, int N,
                   int C) {
  constexpr int B = 256;
  q.submit([&](sycl::handler &h) {
    sycl::local_accessor<float, 1> shm(sycl::range<1>(B), h);
    h.parallel_for<SoftmaxK4>(
        sycl::nd_range<1>(sycl::range<1>((size_t)N * B), sycl::range<1>(B)),
        [=](sycl::nd_item<1> it) {
          int idx = (int)it.get_group(0);
          int tid = (int)it.get_local_id(0);
          int bs = (int)it.get_local_range(0);
          if (idx >= N) return;
          sycl::sub_group sg = it.get_sub_group();
          size_t nsg = sg.get_group_range()[0];
          size_t sgid = sg.get_group_id()[0];
          size_t lane = sg.get_local_id()[0];
          const float *x = d_inp + (size_t)idx * (size_t)C;
          float mx = kNegInf();
          for (int i = tid; i < C; i += bs) mx = sycl::fmax(mx, x[i]);
          float wmax = sycl::reduce_over_group(sg, mx, sycl::maximum<float>());
          if (lane == 0) shm[sgid] = wmax;
          it.barrier(sycl::access::fence_space::local_space);
          if (tid == 0) {
            float v = shm[0];
            for (size_t i = 1; i < nsg; ++i) v = sycl::fmax(v, shm[i]);
            shm[0] = v;
          }
          it.barrier(sycl::access::fence_space::local_space);
          float off = shm[0];
          for (int i = tid; i < C; i += bs)
            d_out[(size_t)idx * (size_t)C + i] = sycl::exp(x[i] - off);
          const float *xo = d_out + (size_t)idx * (size_t)C;
          float sv = 0.0f;
          for (int i = tid; i < C; i += bs) sv += xo[i];
          float wsum = sycl::reduce_over_group(sg, sv, sycl::plus<float>());
          if (lane == 0) shm[sgid] = wsum;
          it.barrier(sycl::access::fence_space::local_space);
          if (tid == 0) {
            float v = shm[0];
