// ---- online SumMax combine (variant 6) ----
struct SumMax {
  float maxval;
  float sum;
};

static inline SumMax sumax_combine(SumMax a, SumMax b) {
  bool a_bigger = (a.maxval > b.maxval);
  SumMax bigger = a_bigger ? a : b;
  SumMax smaller = a_bigger ? b : a;
  SumMax r;
  r.maxval = bigger.maxval;
  r.sum = bigger.sum + smaller.sum * sycl::exp(smaller.maxval - bigger.maxval);
  return r;
}

// sub-group reduction with the online operator, built from shuffles
// (SYCL spelling of cg::reduce(warp, partial, op) in CUDA variant 6).
static inline SumMax summax_reduce_subgroup(sycl::sub_group sg, SumMax part) {
  size_t sgsz = sg.get_local_range()[0];
  for (size_t off = sgsz / 2; off > 0; off >>= 1) {
    SumMax other;
    other.maxval = sycl::shift_group_left(sg, part.maxval, off);
    other.sum = sycl::shift_group_left(sg, part.sum, off);
    part = sumax_combine(part, other);
  }
  SumMax b;
  b.maxval = sycl::group_broadcast(sg, part.maxval, 0);
  b.sum = sycl::group_broadcast(sg, part.sum, 0);
  return b;
}

